OUTER_BANKS_DETAIL_JITTER_MIN_SECONDS = 1.0
OUTER_BANKS_DETAIL_JITTER_MAX_SECONDS = 3.0
OUTER_BANKS_DETAIL_MAX_RETRY_DELAY_SECONDS = 15 * 60


@shared_task
def sync_rss_feeds():
    """Sync all enabled RSS feed sources."""
    from trips.models import RSSFeedSource
    from trips.services.rss_feed_service import RSSFeedService

    service = RSSFeedService()
    sources = RSSFeedSource.objects.filter(is_enabled=True)

    for source in sources:
        try:
            result = service.sync_feed(source)
            logger.info(
                "RSS sync %s: created=%d updated=%d skipped=%d errors=%d",
                source.name,
                result["created"],
                result["updated"],
                result["skipped"],
                result["errors"],
            )
        except Exception:
            logger.exception("RSS sync failed for %s", source.name)


@shared_task
def sync_obx_nps_data():
