    return NPSSyncService().sync_obx_alerts()


def _outer_banks_retry_delay(
    retries: int,
    *,
    retry_after_seconds: int | None = None,
) -> int:
    if retry_after_seconds is not None:
        return max(1, retry_after_seconds + int(random.uniform(1, 5)))  # noqa: S311 - retry jitter, not security

    backoff = min(OUTER_BANKS_DETAIL_MAX_RETRY_DELAY_SECONDS, 60 * (2**retries))
    return max(1, int(backoff + random.uniform(1, 15)))  # noqa: S311 - retry jitter, not security


def _sleep_between_outer_banks_detail_requests() -> None:
    # Sequential pacing here keeps batch hydrations polite even when the same
    # feed contains many items that would otherwise trigger rapid follow-up hits.
    time.sleep(
        random.uniform(  # noqa: S311 - pacing jitter, not security
            OUTER_BANKS_DETAIL_JITTER_MIN_SECONDS,
            OUTER_BANKS_DETAIL_JITTER_MAX_SECONDS,
        )
    )


@shared_task(bind=True, max_retries=4)
def hydrate_outer_banks_event_details_batch_task(
    self,
    source_key: str,
    event_ids: list[int],
    *,
    force: bool = False,
) -> None:
    from trips.models import RegionEvent
    from trips.services.outer_banks_event_detail_hydration import (
        OuterBanksEventDetailHydrationService,
        SourceDetailHydrationRetryableError,
        is_outer_banks_event_source,
        needs_outer_banks_detail_hydration,
    )

    if not is_outer_banks_event_source(source_key):
        logger.info(
            "Skipping source detail hydration for unsupported source '%s'", source_key
        )
        return

    service = OuterBanksEventDetailHydrationService()
    has_fetched_detail = False

    for raw_event_id in event_ids:
        try:
            event = RegionEvent.objects.select_related("event_source").get(
                id=int(raw_event_id)
            )
        except (TypeError, ValueError, RegionEvent.DoesNotExist):
            logger.warning(
                "Skipping missing or invalid RegionEvent id '%s' in source detail hydration batch",
                raw_event_id,
            )
            continue

        if not needs_outer_banks_detail_hydration(event, force=force):
            continue

        if has_fetched_detail:
            _sleep_between_outer_banks_detail_requests()

        try:
            service.hydrate_event(event.id, force=force)
        except SourceDetailHydrationRetryableError as exc:
            if self.request.retries >= self.max_retries:
                service.mark_failed(event.id, str(exc))
                continue
            raise self.retry(
                exc=exc,
                countdown=_outer_banks_retry_delay(
                    self.request.retries,
                    retry_after_seconds=exc.retry_after_seconds,
                ),
            ) from exc
        except Exception as exc:
            service.mark_failed(event.id, str(exc))
            logger.exception(
                "Outer Banks source detail hydration failed for RegionEvent %s",
                event.id,
            )
            continue

        has_fetched_detail = True


@shared_task(
    bind=True,
    max_retries=3,
    default_retry_delay=60,
    autoretry_for=(Exception,),
    retry_backoff=True,
)
def enrich_region_event_place_task(self, region_event_id: int) -> None:
    """Enrich an imported RegionEvent with Google Places data."""
    from trips.services.region_event_place_enrichment import (
        RegionEventPlaceEnrichmentService,
    )

    service = RegionEventPlaceEnrichmentService()
    event = service.enrich_event(region_event_id)
    if (
        event is not None
        and getattr(event, "matched_business_id", None)
        and getattr(event, "location_match_source", "") == "GOOGLE_FALLBACK"
    ):
        backfill_google_import_business_listing_task.delay(event.matched_business_id)


@shared_task
def backfill_google_import_business_listing_task(business_listing_id: int) -> None:
    """Backfill matching RegionEvents after a Google auto-import listing update."""
    from regions.cache import invalidate_explore_cache, invalidate_region_detail_cache
    from trips.models import BusinessListing
    from trips.services.business_listing_google_enrichment import (
        BusinessListingGoogleEnrichmentService,
    )

    try:
        listing = BusinessListing.objects.select_related("region").get(
            id=business_listing_id
        )
    except BusinessListing.DoesNotExist:
        logger.warning(
            "BusinessListing %s not found for Google import backfill",
            business_listing_id,
        )
        return

    service = BusinessListingGoogleEnrichmentService()
    service.backfill_listing_events(listing)
    invalidate_region_detail_cache(listing.region)
    invalidate_explore_cache()


