@shared_task
def generate_trip_photo_thumbnail_task(photo_id: str) -> None:
    """Generate a thumbnail for an uploaded trip video photo."""
    from events.media_services import MediaStorageService
    from trips.models import TripPhoto

    try:
        photo = TripPhoto.objects.select_related("trip").get(id=photo_id)
    except TripPhoto.DoesNotExist:
        logger.warning("TripPhoto %s not found for thumbnail generation", photo_id)
        return

    if photo.media_type != "VIDEO":
        logger.info(
            "Skipping thumbnail generation for non-video TripPhoto %s", photo_id
        )
        return

    thumbnail_key = (
        MediaStorageService.generate_video_thumbnail(
            photo.file_key,
            str(photo.trip_id),
            namespace="trips",
        )
        or ""
    )

    if thumbnail_key:
        photo.thumbnail_key = thumbnail_key
        photo.save(update_fields=["thumbnail_key"])
        logger.info("Generated thumbnail for TripPhoto %s", photo_id)
        return

    logger.warning("Thumbnail generation returned no result for TripPhoto %s", photo_id)


@shared_task(
    bind=True,
    max_retries=3,
    default_retry_delay=60,
    autoretry_for=(Exception,),
    retry_backoff=True,
)
def notify_invite_sent_task(self, invite_id, trips_newly_enabled=False):
    """
    Async task to send notification when a trip invite is sent.
    """
    try:
        invite = TripInvite.objects.get(id=invite_id)

        # Skip if invite status changed from PENDING
        if invite.status != "PENDING":
            logger.info(
                "Skipping notification for invite %s with status %s",
                invite_id,
                invite.status,
            )
            return

        TripNotificationService.notify_invite_sent(
            invite, trips_newly_enabled=trips_newly_enabled
        )
    except TripInvite.DoesNotExist:
        logger.warning("TripInvite %s not found in notify_invite_sent_task", invite_id)


