# Earth's radius in miles for Haversine formula
EARTH_RADIUS_MILES = 3959.0


def annotate_distance(
    queryset,
    lat: float,
    lng: float,
    lat_field: str = "latitude",
    lng_field: str = "longitude",
):
    """
    Annotate queryset with distance from a point using the Haversine formula.

    This uses PostgreSQL's math functions to calculate the great-circle distance
    between two points on Earth's surface.
    """
    # Convert degrees to radians and calculate distance using Haversine formula
    # distance = R * acos(sin(lat1) * sin(lat2) + cos(lat1) * cos(lat2) * cos(lng2 - lng1))
    return queryset.annotate(
        distance_miles=Value(EARTH_RADIUS_MILES)
        * ACos(
            Sin(Radians(Value(lat))) * Sin(Radians(F(lat_field)))
            + Cos(Radians(Value(lat)))
            * Cos(Radians(F(lat_field)))
            * Cos(Radians(F(lng_field)) - Radians(Value(lng)))
        )
    )


def annotate_one_off_priority(queryset):
    """
    Annotate queryset with is_one_off for priority ordering.

    One-off events (recurrence_pattern="NONE") get value 1,
    recurring events get value 0.
    Ordering by -is_one_off puts one-off events first.
    """
    return queryset.annotate(
        is_one_off=Case(
            When(recurrence_pattern="NONE", then=Value(1)),
            default=Value(0),
            output_field=IntegerField(),
        )
    )


