class RegionalAreaViewSet(viewsets.ReadOnlyModelViewSet):
    """ViewSet for RegionalArea model."""

    serializer_class = RegionalAreaSerializer
    permission_classes = [permissions.IsAuthenticated]
    queryset = RegionalArea.objects.filter(is_active=True)

    def get_queryset(self):
        """Filter regional areas by region if specified."""
        queryset = super().get_queryset()
        region_id = self.request.query_params.get("region_id")
        if region_id:
            queryset = queryset.filter(region_id=region_id)
        return queryset.select_related("region")

    @action(detail=False, methods=["get"])
    def nearby(self, request):
        """
        Return regional areas near a given location.

        Query params:
            lat: Latitude (required)
            lng: Longitude (required)
            radius: Search radius in miles (default: 25)
            region_ids: Comma-separated list of region IDs to filter by (optional)
        """
        lat = request.query_params.get("lat")
        lng = request.query_params.get("lng")

        if not lat or not lng:
            return Response(
                {"error": "lat and lng query parameters are required."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        try:
            lat = float(lat)
            lng = float(lng)
        except ValueError:
            return Response(
                {"error": "lat and lng must be valid numbers."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        radius = float(request.query_params.get("radius", 25))
        region_ids = request.query_params.get("region_ids")

        queryset = self.get_queryset()

        # Filter by region IDs if provided
        if region_ids:
            region_id_list = [rid.strip() for rid in region_ids.split(",")]
            queryset = queryset.filter(region_id__in=region_id_list)

        # Annotate with distance and filter by radius
        queryset = annotate_distance(queryset, lat, lng)
        queryset = queryset.filter(distance_miles__lte=radius).order_by(
            "distance_miles"
        )

        serializer = self.get_serializer(queryset, many=True)
        return Response(serializer.data)


