class RegionEventViewSet(viewsets.ModelViewSet):
    """ViewSet for RegionEvent model."""

    serializer_class = RegionEventSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_permissions(self):
        if self.action in [
            "create",
            "update",
            "partial_update",
            "destroy",
            "bulk_create",
        ]:
            return [permissions.IsAdminUser()]
        return [permissions.IsAuthenticated()]

    def get_queryset(self):
        """
        Return region events for regions that are associated with the user's trips.

        All events are annotated with is_one_off for priority sorting
        (one-off events appear before recurring events).
        """
        user = self.request.user
        if user.is_staff:
            queryset = RegionEvent.objects.filter(is_active=True)
        else:
            accessible_trips = trip_queryset_for_user(
                user, Trip.objects.filter(deleted_at__isnull=True)
            )
            queryset = RegionEvent.objects.filter(
                region_calendar__region__trips__in=accessible_trips,
                is_active=True,
            ).distinct()
        return annotate_one_off_priority(
            queryset.select_related(
                "region_calendar__region",
                "regional_area",
                "event_source",
                "created_by",
            )
        )

    def get_serializer_class(self):
        """
        Return appropriate serializer class based on the action.
        """
        if self.action == "create":
            return RegionEventCreateSerializer
        if self.action == "bulk_create":
            return RegionEventBulkCreateSerializer
        if self.action == "occurrences":
            return RegionEventOccurrenceSerializer
        return RegionEventSerializer

    def _paginated_queryset_response(self, queryset):
        page = self.paginate_queryset(queryset)
        if page is not None:
            serializer = self.get_serializer(page, many=True)
            return self.get_paginated_response(serializer.data)
        serializer = self.get_serializer(queryset, many=True)
        return Response(serializer.data)

    def _get_accessible_trip(self, trip_id: int) -> Trip:
        queryset = Trip.objects.filter(deleted_at__isnull=True)
        if not self.request.user.is_staff:
            queryset = trip_queryset_for_user(self.request.user, queryset)
        return get_object_or_404(queryset, id=trip_id)

    def perform_create(self, serializer):
        """
        Create a new region event.
        """
        with transaction.atomic():
            serializer.save(created_by=self.request.user)

    @action(
        detail=False, methods=["post"], permission_classes=[permissions.IsAdminUser]
    )
    def bulk_create(self, request):
        """
        Create multiple region events in a single request.
        """
        serializer = self.get_serializer(
            data=request.data, context={"request": request}
        )
        serializer.is_valid(raise_exception=True)
        events = serializer.save()
        return Response(
            RegionEventSerializer(events, many=True).data,
            status=status.HTTP_201_CREATED,
        )

    @action(detail=False, methods=["get"])
    def by_region(self, request):
        """
