    @action(detail=False, methods=["get"])
    def occurrences(self, request):
        """
        Return day-level occurrence rows for a trip, region, area, or nearby location.
        """
        query_serializer = RegionEventOccurrenceQuerySerializer(
            data=request.query_params
        )
        query_serializer.is_valid(raise_exception=True)
        params = query_serializer.validated_data

        queryset = self.get_queryset()
        start_date = params.get("start_date")
        end_date = params.get("end_date")

        trip_id = params.get("trip_id")
        region_id = params.get("region_id")
        area_id = params.get("area_id")
        category = params.get("category")
        lat = params.get("lat")
        lng = params.get("lng")

        today = timezone.localdate()

        if trip_id is not None:
            trip = self._get_accessible_trip(trip_id)
            if not trip.has_exact_dates:
                return Response(
                    {
                        "error": "Trip dates are required before loading regional events.",
                        "code": "trip_dates_required",
                    },
                    status=status.HTTP_400_BAD_REQUEST,
                )
            queryset = queryset.filter(region_calendar__region__trips__id=trip.id)
            trip_start_date = trip.start_date
            trip_end_date = trip.end_date
            if trip_start_date is None or trip_end_date is None:
                return Response(
                    {
                        "error": "Trip dates are required before loading regional events.",
                        "code": "trip_dates_required",
                    },
                    status=status.HTTP_400_BAD_REQUEST,
                )
            start_date = start_date or max(trip_start_date, today)
            end_date = end_date or trip_end_date
        elif region_id is not None:
            queryset = queryset.filter(region_calendar__region_id=region_id)
        elif area_id is not None:
            area = get_object_or_404(
                RegionalArea.objects.filter(is_active=True), id=area_id
            )
            queryset = queryset.filter(
                latitude__isnull=False,
                longitude__isnull=False,
            )
        else:
            radius = params.get("radius", 15.0)
            queryset = annotate_distance(
                queryset.filter(
                    latitude__isnull=False,
                    longitude__isnull=False,
                ),
                lat,
                lng,
            ).filter(distance_miles__lte=radius)

        start_date = start_date or today
        end_date = end_date or start_date
        if end_date < start_date:
            return Response(
                {"error": "end_date cannot be earlier than start_date."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        if category:
            queryset = queryset.filter(category=category)

        queryset = filter_events_with_occurrences_in_range(
            queryset,
            start_date=start_date,
            end_date=end_date,
        )
        events = list(queryset.order_by("-is_one_off", "start_datetime"))  # type: ignore[misc]
        if trip_id is not None and lat is not None and lng is not None:
            events = attach_distance_to_events(events, lat=lat, lng=lng)

        if area_id is not None:
            events = [
                event
                for event in events
                if event.latitude is not None
                and event.longitude is not None
                and haversine_miles(
                    event.latitude,
                    event.longitude,
                    area.latitude,
                    area.longitude,
                )
                <= area.radius_miles
            ]

        occurrences = build_occurrence_rows(
            events,
            start_date=start_date,
            end_date=end_date,
        )
        response_serializer = self.get_serializer(occurrences, many=True)
        return Response(response_serializer.data)

