    cleaned_data = super().clean() or {}
    date_status = cleaned_data.get("date_status") or Trip.DateStatus.EXACT
    start_date = cleaned_data.get("start_date")
    end_date = cleaned_data.get("end_date")

    if date_status == Trip.DateStatus.UNKNOWN:
        if start_date is not None:
            self.add_error(
                "start_date", _("Start date must be blank when dates are unknown.")
            )
        if end_date is not None:
            self.add_error(
                "end_date", _("End date must be blank when dates are unknown.")
            )
        return cleaned_data

    if start_date is None:
        self.add_error(
            "start_date", _("Start date is required when dates are exact.")
        )
    if end_date is None:
