                                <div class="bg-light rounded p-3 text-center">
                                    <div class="h3 text-primary mb-0">{{ properties.count }}</div>
                                    <small class="text-muted">Properties</small>
                                </div>
                            </div>
                            <div class="col-6">
                                <div class="bg-light rounded p-3 text-center">
                                    <div class="h3 text-primary mb-0">{{ packing_lists.count }}</div>
                                    <small class="text-muted">Packing Lists</small>
                                </div>
                            </div>
                            <div class="col-6">
                                <div class="bg-light rounded p-3 text-center">
                                    <div class="h3 text-primary mb-0">{{ grocery_lists.count }}</div>
                                    <small class="text-muted">Grocery Lists</small>
                                </div>
                            </div>
                        </div>
                    </div>
                    <div class="col-md-6">
                        <h4 class="mb-3">Families</h4>
                        <div class="d-flex flex-wrap gap-2">
                            {% for family in accepted_families %}
                                <span class="badge bg-primary-light text-primary">{{ family.name }}</span>
                            {% endfor %}
                        </div>

                        {% if trip.region %}
                        <h4 class="mb-3 mt-4">Region</h4>
                        <p class="text-muted">{{ trip.region.name }}</p>
                        {% endif %}
                    </div>
                </div>
            </div>

            <!-- Properties Tab -->
            <div class="tab-pane fade" id="properties" role="tabpanel">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h4 class="mb-0">Properties</h4>
                    <a href="{% url 'trips:property_create' trip_pk=trip.pk %}" class="btn btn-sm btn-primary">
                        <i class="bi bi-plus-lg me-1"></i>Add Property
                    </a>
                </div>

                {% if properties %}
                    {% for property in properties %}
                    <div class="property-card {% if property.is_primary %}primary{% endif %}">
                        <div class="d-flex justify-content-between align-items-start">
                            <div>
                                <div class="property-name">
                                    {{ property.name }}
                                    {% if property.is_primary %}
                                        <span class="badge bg-primary ms-2">Primary</span>
                                    {% endif %}
                                </div>
                                <div class="property-address">
                                    <i class="bi bi-geo-alt me-1"></i>{{ property.address }}
                                </div>
                                {% if property.property_url %}
                                <a href="{{ property.property_url }}" target="_blank" class="small">
                                    <i class="bi bi-link-45deg"></i>View Listing
                                </a>
                                {% endif %}
                            </div>
                            <div class="dropdown">
                                <button class="btn btn-sm btn-outline-secondary" data-bs-toggle="dropdown">
                                    <i class="bi bi-three-dots"></i>
                                </button>
                                <ul class="dropdown-menu">
                                    <li><a class="dropdown-item" href="{% url 'trips:property_edit' trip_pk=trip.pk pk=property.pk %}">Edit</a></li>
                                    {% if not property.is_primary %}
                                    <li><a class="dropdown-item" href="{% url 'trips:property_set_primary' trip_pk=trip.pk pk=property.pk %}">Set as Primary</a></li>
                                    {% endif %}
                                    <li><hr class="dropdown-divider"></li>
                                    <li><a class="dropdown-item text-danger" href="{% url 'trips:property_delete' trip_pk=trip.pk pk=property.pk %}">Delete</a></li>
                                </ul>
                            </div>
                        </div>
                    </div>
                    {% endfor %}
                {% else %}
                    <div class="empty-tab">
                        <i class="bi bi-house"></i>
                        <p>No properties added yet</p>
                        <a href="{% url 'trips:property_create' trip_pk=trip.pk %}" class="btn btn-sm btn-outline-primary">Add Property</a>
                    </div>
                {% endif %}
            </div>

            <!-- Members Tab -->
            <div class="tab-pane fade" id="members" role="tabpanel">
                <h4 class="mb-3">Travelers</h4>

                {% if members %}
                    {% for member in members %}
                    <div class="member-card">
                        <div class="member-avatar">
                            {{ member.user.first_name|slice:":1"|default:member.user.username|slice:":1"|upper }}
                        </div>
                        <div class="member-info">
                            <div class="member-name">{{ member.user.get_full_name|default:member.user.username }}</div>
                            <div class="member-dates">
                                <i class="bi bi-calendar3 me-1"></i>
                                {{ member.arrival_date|date:"M d" }} - {{ member.departure_date|date:"M d" }}
                                ({{ member.duration_days }} days)
                            </div>
                        </div>
                    </div>
                    {% endfor %}
                {% else %}
                    <div class="empty-tab">
                        <i class="bi bi-people"></i>
                        <p>No travelers added yet</p>
                    </div>
                {% endif %}
            </div>

            <!-- Packing Tab -->
            <div class="tab-pane fade" id="packing" role="tabpanel">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h4 class="mb-0">Packing Lists</h4>
                    <a href="{% url 'trips:packing_list_create' trip_pk=trip.pk %}" class="btn btn-sm btn-primary">
                        <i class="bi bi-plus-lg me-1"></i>Create List
                    </a>
                </div>

                {% if packing_lists %}
                    {% for list in packing_lists %}
                    <a href="{% url 'trips:packing_list_detail' trip_pk=trip.pk pk=list.pk %}" class="list-card text-decoration-none">
                        <div class="list-info">
                            <h4>{{ list.name }}</h4>
                            <p>{{ list.items.count }} items</p>
                        </div>
                        <div class="list-progress">
                            <div class="progress">
                                <div class="progress-bar bg-primary" style="width: {{ list.completion_percentage }}%"></div>
                            </div>
                            <span class="small text-muted">{{ list.completion_percentage|floatformat:0 }}%</span>
                        </div>
                    </a>
                    {% endfor %}
                {% else %}
                    <div class="empty-tab">
                        <i class="bi bi-luggage"></i>
                        <p>No packing lists created yet</p>
                        <a href="{% url 'trips:packing_list_create' trip_pk=trip.pk %}" class="btn btn-sm btn-outline-primary">Create Packing List</a>
                    </div>
                {% endif %}
            </div>

            <!-- Grocery Tab -->
            <div class="tab-pane fade" id="grocery" role="tabpanel">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h4 class="mb-0">Grocery Lists</h4>
                    <a href="{% url 'trips:grocery_list_create' trip_pk=trip.pk %}" class="btn btn-sm btn-primary">
                        <i class="bi bi-plus-lg me-1"></i>Create List
                    </a>
                </div>

                {% if grocery_lists %}
                    {% for list in grocery_lists %}
                    <a href="{% url 'trips:grocery_list_detail' trip_pk=trip.pk pk=list.pk %}" class="list-card text-decoration-none">
                        <div class="list-info">
                            <h4>{{ list.name }}</h4>
                            <p>{{ list.items.count }} items</p>
                        </div>
                        <div class="list-progress">
                            <div class="progress">
                                <div class="progress-bar bg-success" style="width: {{ list.completion_percentage }}%"></div>
                            </div>
                            <span class="small text-muted">{{ list.completion_percentage|floatformat:0 }}%</span>
                        </div>
                    </a>
                    {% endfor %}
                {% else %}
                    <div class="empty-tab">
                        <i class="bi bi-cart"></i>
                        <p>No grocery lists created yet</p>
                        <a href="{% url 'trips:grocery_list_create' trip_pk=trip.pk %}" class="btn btn-sm btn-outline-primary">Create Grocery List</a>
                    </div>
                {% endif %}
            </div>

            <!-- Meals Tab -->
            <div class="tab-pane fade" id="meals" role="tabpanel">
                {% if meal_plan %}
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h4 class="mb-0">Meal Plan</h4>
                    <a href="{% url 'meals:meal_plan_detail' plan_id=meal_plan.id %}" class="btn btn-sm btn-primary">
                        <i class="bi bi-cup-hot me-1"></i>Open Meal Plan
                    </a>
                </div>
                <div class="list-card">
                    <div class="list-info">
                        <h4>{{ meal_plan.name }}</h4>
                        <p>{{ meal_plan.days.count }} days planned</p>
                    </div>
                    <span class="badge bg-{% if meal_plan.status == 'ACTIVE' %}success{% elif meal_plan.status == 'ARCHIVED' %}secondary{% else %}warning{% endif %}">
                        {{ meal_plan.get_status_display }}
                    </span>
                </div>
                {% else %}
                <div class="empty-tab">
                    <i class="bi bi-cup-hot"></i>
                    <p>No meal plan yet</p>
                    <a href="{% url 'meals:meal_plan_create_for_trip' trip_pk=trip.pk %}" class="btn btn-sm btn-outline-primary">Create Meal Plan</a>
                </div>
                {% endif %}
            </div>

            <!-- Documents Tab -->
            <div class="tab-pane fade" id="documents" role="tabpanel">
                <div class="empty-tab">
                    <i class="bi bi-file-earmark-text"></i>
                    <p>Trip documents feature coming soon</p>
                    <small class="text-muted">Upload and share important trip documents like confirmations, itineraries, and tickets.</small>
                </div>
            </div>

            <!-- Invites Tab (Creator Only) -->
            {% if is_creator %}
            <div class="tab-pane fade" id="invites" role="tabpanel">
                <div class="d-flex justify-content-between align-items-center mb-3">
                    <h4 class="mb-0">Pending Invitations</h4>
                    <form method="post" action="{% url 'trips:invite_family_to_trip' trip_id=trip.pk %}" class="d-inline">
                        {% csrf_token %}
                        <button type="submit" class="btn btn-sm btn-primary">
                            <i class="bi bi-plus-lg me-1"></i>Generate Invite Link
                        </button>
                    </form>
                </div>

                {% if pending_invites %}
                    {% for invite in pending_invites %}
                    <div class="member-card">
                        <div class="member-avatar">
                            <i class="bi bi-envelope"></i>
                        </div>
                        <div class="member-info">
                            <div class="member-name">
                                {% if invite.nickname %}{{ invite.nickname }}{% else %}Invite #{{ forloop.counter }}{% endif %}
                            </div>
                            <div class="member-dates">
                                <i class="bi bi-clock me-1"></i>
                                Created {{ invite.created_at|timesince }} ago
                                {% if invite.expires_at %}
                                | Expires {{ invite.expires_at|date:"M d, Y" }}
                                {% endif %}
                            </div>
                            <div class="small text-muted mt-2">
                                <div class="fw-semibold text-uppercase" style="font-size: 0.7rem; letter-spacing: 0.04em;">Active invite URL</div>
                                <code class="text-break">{{ request.scheme }}://{{ request.get_host }}{% url 'trips:accept_trip_invite_token' token=invite.token %}</code>
                            </div>
                        </div>
                        <div class="d-flex gap-2">
                            <form method="post" action="{% url 'trips:resend_trip_invite' trip_pk=trip.pk invite_pk=invite.pk %}" style="display: inline;">
                                {% csrf_token %}
                                <button type="submit" class="btn btn-sm btn-outline-primary" title="Resend invite link">
                                    <i class="bi bi-arrow-repeat"></i>
                                </button>
                            </form>
                            <form method="post" action="{% url 'trips:cancel_trip_invite' trip_pk=trip.pk invite_pk=invite.pk %}" style="display: inline;">
                                {% csrf_token %}
                                <button type="submit" class="btn btn-sm btn-outline-danger" title="Cancel invitation" onclick="return confirm('Cancel this invitation?')">
                                    <i class="bi bi-x-lg"></i>
                                </button>
                            </form>
                        </div>
                    </div>
                    {% endfor %}
                {% else %}
                    <div class="empty-tab">
                        <i class="bi bi-envelope"></i>
                        <p>No pending invitations</p>
                        <form method="post" action="{% url 'trips:invite_family_to_trip' trip_id=trip.pk %}" class="d-inline">
                            {% csrf_token %}
                            <button type="submit" class="btn btn-sm btn-outline-primary">Invite a Family</button>
                        </form>
                    </div>
                {% endif %}
            </div>
            {% endif %}
        </div>
    </div>
</div>
{% endblock %}
