{% extends "base.html" %}
{% load static %}

{% block title %}Delete Trip{% endblock %}

{% block extra_css %}
<style>
    .delete-container {
        max-width: 500px;
        margin: var(--space-8) auto;
    }

    .delete-card {
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-6);
        text-align: center;
    }

    .delete-icon {
        width: 64px;
        height: 64px;
        background: var(--danger-light, #fee2e2);
        border-radius: var(--radius-full);
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 0 auto var(--space-4);
    }

    .delete-icon i {
        font-size: 2rem;
        color: var(--danger, #dc2626);
    }

    .delete-card h1 {
        font-size: var(--font-size-xl);
        font-weight: 600;
        margin-bottom: var(--space-2);
    }

    .delete-card p {
        color: var(--gray-600);
        margin-bottom: var(--space-4);
    }

    .trip-summary {
        background: var(--gray-50);
        border-radius: var(--radius-md);
        padding: var(--space-4);
        margin-bottom: var(--space-4);
        text-align: left;
    }

    .trip-summary-name {
        font-weight: 600;
        color: var(--gray-900);
    }

    .trip-summary-meta {
        font-size: var(--font-size-sm);
        color: var(--gray-500);
        margin-top: var(--space-1);
    }

    .delete-warning {
        background: var(--warning-light, #fef3c7);
        color: var(--warning, #d97706);
        padding: var(--space-3);
        border-radius: var(--radius-md);
        font-size: var(--font-size-sm);
        margin-bottom: var(--space-4);
        display: flex;
        align-items: center;
        gap: var(--space-2);
    }

    .delete-actions {
        display: flex;
        gap: var(--space-3);
        justify-content: center;
    }

    .delete-actions .btn {
        min-width: 120px;
    }
</style>
{% endblock %}

{% block content %}
<div class="container">
    <div class="delete-container">
        <div class="delete-card">
            <div class="delete-icon">
                <i class="bi bi-trash"></i>
            </div>

            <h1>Delete Trip?</h1>
            <p>Are you sure you want to delete this trip? This action cannot be undone.</p>

            <div class="trip-summary">
                <div class="trip-summary-name">{{ trip.name }}</div>
                <div class="trip-summary-meta">
                    <i class="bi bi-geo-alt me-1"></i>{{ trip.location }}
                    <span class="mx-2">|</span>
                    <i class="bi bi-calendar3 me-1"></i>{{ trip.start_date|date:"M d" }} - {{ trip.end_date|date:"M d, Y" }}
                </div>
            </div>

            <div class="delete-warning">
                <i class="bi bi-exclamation-triangle"></i>
                <span>All packing lists, grocery lists, and properties will also be deleted.</span>
            </div>

            <form method="post">
                {% csrf_token %}
                <div class="delete-actions">
                    <a href="{% url 'trips:trip_detail' pk=trip.pk %}" class="btn btn-outline-secondary">
                        Cancel
                    </a>
                    <button type="submit" class="btn btn-danger">
                        <i class="bi bi-trash me-1"></i>Delete Trip
                    </button>
                </div>
            </form>
        </div>
    </div>
</div>
{% endblock %}

