{% if row.preference.note %}
<p class="text-muted">{{ row.preference.note }}</p>
{% elif not row.can_edit %}
<p class="text-muted mb-0">No note yet.</p>
{% endif %}

{% if row.can_edit %}
<form method="post" class="mt-3">
    {% csrf_token %}
    <input type="hidden" name="family_group" value="{{ row.family.id }}">
    <div class="mb-3">
        <label class="form-label fw-semibold">Decision</label>
        <div class="d-flex flex-wrap gap-3">
            {% for value, label in stance_choices %}
            <div class="form-check">
                <input class="form-check-input" type="radio" name="stance" id="stance-top-{{ row.family.id }}-{{ value }}" value="{{ value }}" {% if row.preference and row.preference.stance == value %}checked{% endif %}>
                <label class="form-check-label" for="stance-top-{{ row.family.id }}-{{ value }}">{{ label }}</label>
            </div>
            {% endfor %}

