{% load static %}

{% block title %}{% if trip %}Edit Trip{% else %}Plan a Trip{% endif %}{% endblock %}

{% block extra_css %}
<style>
    .form-container {
        max-width: 700px;
        margin: 0 auto;
    }

    .form-card {
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        padding: var(--space-6);
    }

    .form-header {
        margin-bottom: var(--space-6);
        padding-bottom: var(--space-4);
        border-bottom: 1px solid var(--gray-200);
    }

    .form-header h1 {
        font-size: var(--font-size-2xl);
        font-weight: 600;
        margin-bottom: var(--space-2);
    }

    .form-header p {
        color: var(--gray-500);
        margin: 0;
    }

    .form-section {
        margin-bottom: var(--space-6);
    }

    .form-section-title {
        font-size: var(--font-size-lg);
        font-weight: 600;
        color: var(--gray-900);
        margin-bottom: var(--space-4);
        display: flex;
        align-items: center;
        gap: var(--space-2);
    }

    .form-section-title i {
        color: var(--primary);
    }

    .date-row {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: var(--space-4);
    }

    .family-checkboxes {
        display: flex;
        flex-direction: column;
        gap: var(--space-2);
    }

    .family-checkbox-item {
        display: flex;
        align-items: center;
        gap: var(--space-2);
        padding: var(--space-3);
        background: var(--gray-50);
        border-radius: var(--radius-md);
        cursor: pointer;
        transition: all var(--transition-fast);
    }

    .family-checkbox-item:hover {
        background: var(--primary-light);
    }

    .family-checkbox-item input[type="checkbox"] {
        width: 18px;
        height: 18px;
    }

    .form-actions {
        display: flex;
        justify-content: space-between;
        align-items: center;
        padding-top: var(--space-4);
        border-top: 1px solid var(--gray-200);
        margin-top: var(--space-4);
    }

    .form-check-inline {
        display: flex;
        align-items: center;
        gap: var(--space-2);
        padding: var(--space-3);
        background: var(--gray-50);
        border-radius: var(--radius-md);
    }

    /* Mobile Responsive */
    @media (max-width: 768px) {
        .date-row {
            grid-template-columns: 1fr;
        }

        .form-actions {
            flex-direction: column;
            gap: var(--space-3);
        }

        .form-actions > * {
            width: 100%;
        }
    }
</style>
{% endblock %}

{% block content %}
<div class="container">
    <div class="form-container">
        <div class="form-card">
            <div class="form-header">
                <h1>
                    <i class="bi bi-umbrella-beach me-2"></i>
                    {% if trip %}Edit Trip{% else %}Plan a Trip{% endif %}
                </h1>
                <p>{% if trip %}Update your trip details{% else %}Start planning your next family adventure{% endif %}</p>
            </div>

            <form method="post">
                {% csrf_token %}

                <!-- Basic Info -->
                <div class="form-section">
                    <h2 class="form-section-title">
                        <i class="bi bi-info-circle"></i>
                        Basic Information
                    </h2>

                    <div class="mb-3">
                        <label for="{{ form.name.id_for_label }}" class="form-label">Trip Name *</label>
                        <input type="text"
                               class="form-control {% if form.name.errors %}is-invalid{% endif %}"
                               id="{{ form.name.id_for_label }}"
                               name="name"
                               value="{{ form.name.value|default:'' }}"
                               placeholder="e.g., Summer Beach Vacation 2025"
                               required>
                        {% if form.name.errors %}
                            <div class="invalid-feedback">{{ form.name.errors.0 }}</div>
                        {% endif %}
                    </div>

                    <div class="mb-3">
                        <label for="{{ form.description.id_for_label }}" class="form-label">Description</label>
                        <textarea class="form-control {% if form.description.errors %}is-invalid{% endif %}"
                                  id="{{ form.description.id_for_label }}"
                                  name="description"
                                  rows="3"
                                  placeholder="Add details about your trip...">{{ form.description.value|default:'' }}</textarea>
                        {% if form.description.errors %}
                            <div class="invalid-feedback">{{ form.description.errors.0 }}</div>
                        {% endif %}
                    </div>
                </div>

                <!-- Location & Dates -->
                <div class="form-section">
                    <h2 class="form-section-title">
                        <i class="bi bi-geo-alt"></i>
                        Location & Dates
                    </h2>

                    <div class="mb-3">
                        <label for="{{ form.location.id_for_label }}" class="form-label">Location *</label>
                        <input type="text"
                               class="form-control {% if form.location.errors %}is-invalid{% endif %}"
                               id="{{ form.location.id_for_label }}"
                               name="location"
                               value="{{ form.location.value|default:'' }}"
                               placeholder="e.g., Ocean City, NJ"
                               required>
                        {% if form.location.errors %}
                            <div class="invalid-feedback">{{ form.location.errors.0 }}</div>
                        {% endif %}
                    </div>

                    <div class="mb-3">
                        <label for="{{ form.region.id_for_label }}" class="form-label">Region (Optional)</label>
                        <select class="form-select {% if form.region.errors %}is-invalid{% endif %}"
                                id="{{ form.region.id_for_label }}"
                                name="region">
                            <option value="">Select a region...</option>
                            {% for choice in form.region.field.queryset %}
                                <option value="{{ choice.pk }}" {% if form.region.value == choice.pk|stringformat:'s' %}selected{% endif %}>
                                    {{ choice.name }}
                                </option>
                            {% endfor %}
                        </select>
                        {% if form.region.errors %}
                            <div class="invalid-feedback">{{ form.region.errors.0 }}</div>
                        {% endif %}
                        <div class="form-text">Select a region for local event calendars and recommendations.</div>
                    </div>

                    <div class="date-row">
                        <div class="mb-3">
                            <label for="{{ form.start_date.id_for_label }}" class="form-label">Start Date *</label>
                            <input type="date"
                                   class="form-control {% if form.start_date.errors %}is-invalid{% endif %}"
                                   id="{{ form.start_date.id_for_label }}"
                                   name="start_date"
                                   value="{{ form.start_date.value|date:'Y-m-d'|default:'' }}"
                                   required>
                            {% if form.start_date.errors %}
                                <div class="invalid-feedback">{{ form.start_date.errors.0 }}</div>
                            {% endif %}
                        </div>

                        <div class="mb-3">
                            <label for="{{ form.end_date.id_for_label }}" class="form-label">End Date *</label>
                            <input type="date"
                                   class="form-control {% if form.end_date.errors %}is-invalid{% endif %}"
                                   id="{{ form.end_date.id_for_label }}"
                                   name="end_date"
                                   value="{{ form.end_date.value|date:'Y-m-d'|default:'' }}"
                                   required>
                            {% if form.end_date.errors %}
                                <div class="invalid-feedback">{{ form.end_date.errors.0 }}</div>
                            {% endif %}
                        </div>
                    </div>
                </div>

                <!-- Family Selection -->
                <div class="form-section">
                    <h2 class="form-section-title">
                        <i class="bi bi-people"></i>
                        Family Groups
                    </h2>

                    <p class="text-muted small mb-3">Select which families will be part of this trip.</p>

                    <div class="family-checkboxes">
                        {% for checkbox in form.family_groups %}
                            <label class="family-checkbox-item">
                                {{ checkbox.tag }}
                                <span>{{ checkbox.choice_label }}</span>
                            </label>
                        {% endfor %}
                    </div>
                    {% if form.family_groups.errors %}
                        <div class="text-danger small mt-2">{{ form.family_groups.errors.0 }}</div>
                    {% endif %}
                </div>

                <!-- Settings -->
                <div class="form-section">
                    <h2 class="form-section-title">
                        <i class="bi bi-gear"></i>
                        Settings
                    </h2>

                    <div class="form-check-inline">
                        <input type="checkbox"
                               class="form-check-input"
                               id="{{ form.gamification_enabled.id_for_label }}"
                               name="gamification_enabled"
                               {% if form.gamification_enabled.value %}checked{% endif %}>
                        <label class="form-check-label" for="{{ form.gamification_enabled.id_for_label }}">
                            <strong>Enable Trip Quests</strong>
                            <span class="d-block text-muted small">Get guided through trip planning with fun quests and achievements.</span>
                        </label>
                    </div>
                </div>

                <!-- Form Actions -->
                <div class="form-actions">
                    <a href="{% if trip %}{% url 'trips:trip_detail' pk=trip.pk %}{% else %}{% url 'trips:trip_list' %}{% endif %}" class="btn btn-outline-secondary">
                        Cancel
                    </a>
                    <button type="submit" class="btn btn-primary">
                        <i class="bi bi-check-lg me-1"></i>
                        {% if trip %}Save Changes{% else %}Create Trip{% endif %}
                    </button>
                </div>
            </form>
        </div>
    </div>
</div>
{% endblock %}
