{% extends "base.html" %}
{% load i18n %}

{% block title %}{% trans "Choose Family to Join Trip" %}{% endblock %}

{% block content %}
<div class="container mt-4">
    <div class="row justify-content-center">
        <div class="col-md-8">
            <div class="card">
                <div class="card-header">
                    <h2>{% trans "Join Trip:" %} {{ trip.name }}</h2>
                </div>
                <div class="card-body">
                    <p>{% trans "You have been invited to join the trip:" %} <strong>{{ trip.name }}</strong>.</p>
                    {% if trip.has_exact_dates %}
                        <p>{% blocktrans with start_date=trip.start_date|date:"F j, Y" end_date=trip.end_date|date:"F j, Y" %}
                            This trip runs from {{ start_date }} to {{ end_date }}.
                        {% endblocktrans %}</p>
                    {% else %}
                        <p>{% trans "Trip dates are still TBD." %}</p>
                    {% endif %}
                    <p>{% trans "Since you administer multiple families, please select which family you would like to add to this trip plan." %}</p>

                    <form method="post" action="{% url 'trips:accept_trip_invite_token' token=invite.token %}">
                        {% csrf_token %}

                        {% if form.non_field_errors %}
                            <div class="alert alert-danger">
                                {% for error in form.non_field_errors %}
                                    {{ error }}
                                {% endfor %}
                            </div>
                        {% endif %}

                        <div class="mb-3">
                            {{ form.family.label_tag }}
                            {% for radio in form.family %}
                                <div class="form-check">
                                    {{ radio.tag }}
                                    <label class="form-check-label" for="{{ radio.id_for_label }}">
                                        {{ radio.choice_label }}
                                    </label>
                                </div>
                            {% endfor %}
                            {% if form.family.errors %}
                                <div class="invalid-feedback d-block">
                                    {% for error in form.family.errors %}
                                        {{ error }}
                                    {% endfor %}
                                </div>
                            {% endif %}
                        </div>

                        <button type="submit" class="btn btn-primary">{% trans "Join Trip with Selected Family" %}</button>
                        <a href="{% url 'dashboard' %}" class="btn btn-secondary">{% trans "Cancel" %}</a>
                    </form>
                </div>
            </div>
        </div>
    </div>
</div>
{% endblock content %}

