{% extends "base.html" %}
{% load static %}

{% block title %}My Trips{% endblock %}

{% block extra_css %}
<style>
    .trips-container {
        margin-top: var(--space-4);
    }

    .trip-section {
        margin-bottom: var(--space-6);
    }

    .section-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: var(--space-4);
    }

    .section-header h2 {
        font-size: var(--font-size-xl);
        font-weight: 600;
        color: var(--gray-900);
        margin: 0;
    }

    .section-header .badge {
        font-size: var(--font-size-sm);
        padding: 4px 12px;
    }

    /* Trip Cards Grid */
    .trip-grid {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
        gap: var(--space-4);
    }

    /* Trip Card */
    .trip-card {
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
        overflow: hidden;
        transition: all var(--transition-fast);
    }

    .trip-card:hover {
        box-shadow: var(--shadow-lg);
        transform: translateY(-2px);
    }

    .trip-card-header {
        padding: var(--space-4);
        border-bottom: 1px solid var(--gray-100);
    }

    .trip-card-title {
        font-size: var(--font-size-lg);
        font-weight: 600;
        color: var(--gray-900);
        margin-bottom: var(--space-1);
    }

    .trip-card-title a {
        text-decoration: none;
        color: inherit;
    }

    .trip-card-title a:hover {
        color: var(--primary);
    }

    .trip-card-location {
        font-size: var(--font-size-sm);
        color: var(--gray-500);
        display: flex;
        align-items: center;
        gap: var(--space-1);
    }

    .trip-card-body {
        padding: var(--space-4);
    }

    .trip-dates {
        display: flex;
        align-items: center;
        gap: var(--space-2);
        font-size: var(--font-size-sm);
        color: var(--gray-600);
        margin-bottom: var(--space-3);
    }

    .trip-dates i {
        color: var(--primary);
    }

    .trip-meta {
        display: flex;
        flex-wrap: wrap;
        gap: var(--space-3);
        font-size: var(--font-size-sm);
        color: var(--gray-500);
    }

    .trip-meta-item {
        display: flex;
        align-items: center;
        gap: var(--space-1);
    }

    .trip-card-footer {
        padding: var(--space-3) var(--space-4);
        border-top: 1px solid var(--gray-100);
        background: var(--gray-50);
    }

    .trip-families {
        display: flex;
        flex-wrap: wrap;
        gap: var(--space-1);
    }

    .trip-families .badge {
        font-size: var(--font-size-xs);
    }

    /* Status Badge */
    .status-badge {
        font-size: var(--font-size-xs);
        padding: 2px 8px;
        border-radius: var(--radius-full);
        font-weight: 500;
    }

    .status-badge.active {
        background: var(--success-light, #d1fae5);
        color: var(--success, #059669);
    }

    .status-badge.upcoming {
        background: var(--primary-light);
        color: var(--primary);
    }

    .status-badge.past {
        background: var(--gray-200);
        color: var(--gray-600);
    }

    /* Empty State */
    .empty-state {
        text-align: center;
        padding: var(--space-8) var(--space-4);
        background: var(--white);
        border-radius: var(--radius-lg);
        box-shadow: var(--shadow);
    }

    .empty-state > i {
        font-size: 2.5rem;
        color: var(--gray-300);
        margin-bottom: var(--space-3);
        display: block;
    }

    .empty-state h3 {
        color: var(--gray-700);
        margin-bottom: var(--space-2);
        font-size: var(--font-size-xl);
    }

    .empty-state p {
        color: var(--gray-500);
        margin-bottom: var(--space-4);
    }

    .empty-state .btn {
        padding: var(--space-2) var(--space-4);
    }

    /* Mobile Responsive */
    @media (max-width: 768px) {
        .trip-grid {
            grid-template-columns: 1fr;
        }
    }
</style>
{% endblock %}

{% block content %}
<div class="container">
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h1><i class="bi bi-umbrella-beach me-2"></i>My Trips</h1>
        <a href="{% url 'trips:trip_create' %}" class="btn btn-primary">
            <i class="bi bi-plus-lg me-2"></i>Plan a Trip
        </a>
    </div>

    <div class="trips-container">
        <!-- Active Trips -->
        {% if active_trips %}
        <section class="trip-section">
            <div class="section-header">
                <h2><i class="bi bi-geo-alt-fill me-2 text-success"></i>Active Trips</h2>
                <span class="badge bg-success">{{ active_trips|length }} Active</span>
            </div>
            <div class="trip-grid">
                {% for trip in active_trips %}
                    {% include "trips/partials/_trip_card.html" with trip=trip status="active" %}
                {% endfor %}
            </div>
        </section>
        {% endif %}

        <!-- Upcoming Trips -->
        {% if upcoming_trips %}
        <section class="trip-section">
            <div class="section-header">
                <h2><i class="bi bi-calendar-event me-2 text-primary"></i>Upcoming Trips</h2>
                <span class="badge bg-primary">{{ upcoming_trips|length }} Upcoming</span>
            </div>
            <div class="trip-grid">
                {% for trip in upcoming_trips %}
                    {% include "trips/partials/_trip_card.html" with trip=trip status="upcoming" %}
                {% endfor %}
            </div>
        </section>
        {% endif %}

        <!-- Past Trips -->
        {% if past_trips %}
        <section class="trip-section">
            <div class="section-header">
                <h2><i class="bi bi-clock-history me-2 text-muted"></i>Past Trips</h2>
                <span class="badge bg-secondary">{{ past_trips|length }} Past</span>
            </div>
            <div class="trip-grid">
                {% for trip in past_trips %}
                    {% include "trips/partials/_trip_card.html" with trip=trip status="past" %}
                {% endfor %}
            </div>
        </section>
        {% endif %}

        <!-- No Trips -->
        {% if not active_trips and not upcoming_trips and not past_trips %}
        <div class="empty-state">
            <i class="bi bi-umbrella-beach"></i>
            <h3>No trips planned yet</h3>
            <p>Start planning your next family adventure!</p>
            <a href="{% url 'trips:trip_create' %}" class="btn btn-primary">
                <i class="bi bi-plus-lg me-2"></i>Plan Your First Trip
            </a>
        </div>
        {% endif %}
    </div>
</div>
{% endblock %}

